Hello,
I came across inconsistency between scsynth and supernova when querying the node tree. Scsynth responds to the "/g_queryTree" message with large OSC messages, while supernova reports

> unhandled exception while running callback: send_to: Message too long

when the reply message would exceed around 9250 bytes. 
It prevents from using this mechanism to track synth status in slightly more complex pieces.
This was tested on a recent development build on macos 10.12. Reproducer:
```
(
var maxsynth = 241; //OK - osc message size 9216 bytes
// var maxsynth = 242; //supernova reports message too long (when running scsynth, SC reports osc message size 9256)

Server.supernova;
// Server.scsynth; //for comparison

s.waitForBoot({
	var defName = \abcdefgh;

	SynthDef(defName, {arg amp = 0;
		var sig = PinkNoise.ar(1);
		Out.ar(0, sig * amp);
	}).send(s);

	p = ParGroup.new;

	fork{
		s.sync;
		"starting synths:".postln;
		maxsynth.do({
			Synth(defName, [\amp, 0], target: p);
			".".post;
			0.025.wait;
		});
		postf("\n% synths launched.\n", maxsynth);
		OSCFunc({arg msg;
			~msg = msg;
			msg.postcs;
			"number of elements: ".post; msg.size.postln;
			"OSC message size (bytes): ".post; msg.msgSize.postln;
		}, '/g_queryTree.reply').oneShot;
		s.sendMsg("/g_queryTree", 0, 1);
	}
})
)
```
This can also be seen with smaller number of synths, that have more arguments:
```
(
var maxsynth = 103; //OK - osc message size 9124 bytes
// var maxsynth = 104; //supernova reports message too long (when running scsynth, SC reports osc message size 10044)

Server.supernova;
// Server.scsynth; //for comparison

s.waitForBoot({
	var defName = \abcdefgh;

	SynthDef(defName, {arg amp = 0, out = 0, freq = 100, att = 0.1, rel = 2, buffer = 0;
		var sig = PinkNoise.ar(1);
		Out.ar(0, sig * amp);
	}).send(s);

	p = ParGroup.new;

	fork{
		s.sync;
		"starting synths:".postln;
		maxsynth.do({
			Synth(defName, [\amp, 0], target: p);
			".".post;
			0.025.wait;
		});
		postf("\n% synths launched.\n", maxsynth);
		OSCFunc({arg msg;
			~msg = msg;
			// msg.postcs;
			"number of elements: ".post; msg.size.postln;
			"OSC message size (bytes): ".post; msg.msgSize.postln;
		}, '/g_queryTree.reply').oneShot;
		s.sendMsg("/g_queryTree", 0, 1);
	}
})
)
```

